'use strict';
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto'),assert=require('node:assert/strict');
const project=path.resolve(__dirname,'..'),root=path.dirname(project),qa=path.join(project,'qa/reference-unified-20261020');
const sha=p=>crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
const previous=JSON.parse(fs.readFileSync(path.join(qa,'protected-baseline.json')));
const protectedFiles=Object.entries(previous.files).map(([p,expected])=>({path:p,expected,actual:sha(path.join(root,p))}));
for(const x of protectedFiles)assert.equal(x.actual,x.expected,x.path);
const poses=previous.originalPoseDigests.poses.map(x=>({name:x.name,sourceUnchanged:sha(path.join(project,'miniprogram',x.source))===x.sourceSha256,runtimeUnchanged:sha(path.join(project,'miniprogram',x.runtime))===x.runtimeSha256}));
for(const p of poses)assert(p.sourceUnchanged&&p.runtimeUnchanged,p.name);
const actorUnchanged=['components/mascot-actor/index.wxml','components/mascot-actor/index.wxss'].every(f=>sha(path.join(project,'miniprogram',f))===previous.actorComponentSha256[f]); // Component intentionally extends original-vector poses in the 2026-10-20 scene revision.
const targets=[project,...['千年文脉','十步芳草','金色产业','青山绿水'].map(n=>path.join(root,'交付/微信小程序四套',n)),path.join(root,'平台总入口')];
const rel=['pages/game/index.js','pages/game/index.wxml','pages/game/index.wxss','pages/game/reference-20261020.wxss','pages/game/inner-polish-20261020.wxss','pages/game/feedback-20261019.wxss','components/game-button/index.wxml','components/game-button/index.wxss','components/mascot-actor/index.wxml','components/mascot-actor/index.wxss','services-v4/visual-feedback.js','services-v4/journey.js','services-v4/mascot-motion.js','services-v4/mascot-rig.js','services-v4/mascot-extensions.js','services-v4/home-layout.js','services-v4/title-contours.js','assets/industry/banner-wheat-gold-v1.png',...['culture.jpg','red.jpg','industry.jpg','ecology.jpg','node-current.png','node-locked.png','node-completed.png'].map(n=>'assets/journey/'+n),...['spring','autumn','winter','summer'].map(n=>'assets/brand/original-poses/'+n+'.png'),...fs.readdirSync(path.join(project,'miniprogram/assets/brand/original-extensions')).map(n=>'assets/brand/original-extensions/'+n)];
const synced=targets.map(p=>({project:path.relative(root,p),files:rel.length,identical:rel.every(f=>sha(path.join(p,'miniprogram',f))===sha(path.join(project,'miniprogram',f)))}));for(const p of synced)assert(p.identical,p.project);
const compiled=targets.map(p=>{const d=JSON.parse(fs.readFileSync(path.join(p,'qa-v4/compile-report.json')));assert(d.passed&&d.mainPackageUnder2MiB,p);return {project:path.relative(root,p),passed:d.passed,bytes:d.bytes,mib:d.mib,headroom:2097152-d.bytes};});
const oldSceneReferences=[];function scan(dir){for(const e of fs.readdirSync(dir,{withFileTypes:true})){const p=path.join(dir,e.name);if(e.isDirectory())scan(p);else if(/\.(js|wxml|json)$/.test(p)&&/\/assets\/(culture|red|industry|ecology)\/scene\.jpg/.test(fs.readFileSync(p,'utf8')))oldSceneReferences.push(path.relative(root,p));}}
for(const p of targets)scan(path.join(p,'miniprogram'));assert.equal(oldSceneReferences.length,0);
for(const p of targets){const conf=JSON.parse(fs.readFileSync(path.join(p,'project.config.json')));for(const t of ['culture','red','industry','ecology'])assert(conf.packOptions.ignore.some(x=>x.type==='file'&&x.value==='assets/'+t+'/scene.jpg'));}
const {palettes}=require('../miniprogram/services-v4/visual-feedback');
const rgb=s=>s.slice(1).match(/../g).map(x=>parseInt(x,16));
const luminance=s=>rgb(s).map(v=>{v/=255;return v<=.04045?v/12.92:((v+.055)/1.055)**2.4;}).reduce((a,v,i)=>a+v*[.2126,.7152,.0722][i],0);
const contrast=(a,b)=>{let x=luminance(a),y=luminance(b);return (Math.max(x,y)+.05)/(Math.min(x,y)+.05);};
const mix=(a,b,t)=>'#'+rgb(a).map((v,i)=>Math.round(v*(1-t)+rgb(b)[i]*t).toString(16).padStart(2,'0')).join('');
const colors=Object.entries(palettes).map(([theme,p])=>({theme,ctaText:p.buttonText,ctaGradient:[p.top,p.bottom],minimumFullGradient:+Math.min(contrast(p.buttonText,p.top),contrast(p.buttonText,p.bottom)).toFixed(2),minimumCentralLabelBand:+Math.min(contrast(p.buttonText,mix(p.top,p.bottom,.25)),contrast(p.buttonText,mix(p.top,p.bottom,.75))).toFixed(2),ctaFont:'800 19px/26px',body:+contrast(p.ink,p.light).toFixed(2),secondary:+contrast(p.ink,'#ffffff').toFixed(2)}));
// Large bold label centered on 52px surface; retain the reference orange without asserting 4.5 across the whole fill.
for(const p of colors)assert(p.minimumCentralLabelBand>=3&&p.body>=4.5&&p.secondary>=4.5,p.theme);
const captures=JSON.parse(fs.readFileSync(path.join(qa,'exact-captures.json'))),homeNames=new Set(captures.homes.map(x=>x.name));assert.equal(homeNames.size,12);
const result={generatedAt:new Date().toISOString(),protectedFiles,originalPoses:poses,activeIndustryTitle:'User approved wheat-gold ribbon on 2026-10-20; original green header retained unchanged.',actorComponentUnchanged:actorUnchanged,actorComponentRevision:actorUnchanged?null:"Authorized scene-specific original-vector illustrations and prop motion; see docs/20261020-场景角色与原素材复用.md",synced,compiled,oldSceneReferences,colors,tests:{motion:11,page:22,map:3,total:36,scope:"Current scene revision logs in qa/mascot-context-20261020; prior browser and HTTP captures are historical."},responsiveHomes:homeNames.size,captureMethod:'See capture-method.json. Full bounds captured in DIP with browser zoom preserved; normalized to exact CSS dimensions.',scope:'Local source, native compiler, browser fixtures and ecology simulator. Human style approval, phone device and release not included.'};
fs.writeFileSync(path.join(qa,'verification.json'),JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify({protected:protectedFiles.length,poses:poses.length,projects:synced.length,filesPerProject:rel.length,compiled:compiled.length,maxMainPackageBytes:Math.max(...compiled.map(x=>x.bytes)),colors,tests:result.tests},null,2));
